import { motion } from "framer-motion";
import { Lightbulb, Clock, Package, TrendingUp } from "lucide-react";
import { useState } from "react";

function Hero() {
  const [showProfileMenu, setShowProfileMenu] = useState(false);

  const fadeUp = {
    hidden: { opacity: 0, y: 30 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.7, ease: [0.22, 1, 0.36, 1] } },
  };

  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.12,
      },
    },
  };

  return (
    <main
      style={{
        minHeight: "100vh",
        background: "#0a0a0a",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Navigation */}
      <nav
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "24px 80px",
          background: "rgba(10, 10, 10, 0.95)",
          backdropFilter: "blur(20px)",
          borderBottom: "1px solid rgba(255, 255, 255, 0.08)",
          position: "sticky",
          top: 0,
          zIndex: 100,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
          <div
            style={{
              width: "36px",
              height: "36px",
              background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              borderRadius: "6px",
              boxShadow: "0 4px 12px rgba(255, 107, 53, 0.3)",
            }}
          >
            <span style={{ color: "#fff", fontSize: "20px", fontWeight: "800", letterSpacing: "-0.5px" }}>A</span>
          </div>
          <span style={{ fontSize: "22px", fontWeight: "700", color: "#fff", letterSpacing: "-0.5px" }}>ASSEMBLE</span>
        </div>

        <div style={{ display: "flex", gap: "48px", alignItems: "center" }}>
          <a href="#" style={{ 
            color: "#ff6b35", 
            textDecoration: "none", 
            fontSize: "14px", 
            fontWeight: "600", 
            letterSpacing: "-0.2px",
            borderBottom: "2px solid #ff6b35",
            paddingBottom: "4px",
            transition: "all 0.3s ease"
          }}>
            My Project
          </a>
          <a href="#" style={{ 
            color: "#a0a0a0", 
            textDecoration: "none", 
            fontSize: "14px", 
            fontWeight: "500",
            letterSpacing: "-0.2px",
            transition: "color 0.3s ease"
          }}
          onMouseEnter={(e) => e.currentTarget.style.color = "#fff"}
          onMouseLeave={(e) => e.currentTarget.style.color = "#a0a0a0"}
          >
            Resources
          </a>
          <a href="#" style={{ 
            color: "#a0a0a0", 
            textDecoration: "none", 
            fontSize: "14px", 
            fontWeight: "500",
            letterSpacing: "-0.2px",
            transition: "color 0.3s ease"
          }}
          onMouseEnter={(e) => e.currentTarget.style.color = "#fff"}
          onMouseLeave={(e) => e.currentTarget.style.color = "#a0a0a0"}
          >
            Library
          </a>
          <a href="#" style={{ 
            color: "#a0a0a0", 
            textDecoration: "none", 
            fontSize: "14px", 
            fontWeight: "500",
            letterSpacing: "-0.2px",
            transition: "color 0.3s ease"
          }}
          onMouseEnter={(e) => e.currentTarget.style.color = "#fff"}
          onMouseLeave={(e) => e.currentTarget.style.color = "#a0a0a0"}
          >
            About Us
          </a>
        </div>

        <div style={{ display: "flex", gap: "24px", alignItems: "center" }}>
          <button style={{ 
            background: "none", 
            border: "none", 
            cursor: "pointer", 
            fontSize: "16px", 
            color: "#a0a0a0", 
            padding: "8px",
            transition: "color 0.3s ease"
          }}
          onMouseEnter={(e) => e.currentTarget.style.color = "#fff"}
          onMouseLeave={(e) => e.currentTarget.style.color = "#a0a0a0"}
          >
            🔔
          </button>
          <button style={{ 
            background: "none", 
            border: "none", 
            cursor: "pointer", 
            fontSize: "16px", 
            color: "#a0a0a0", 
            padding: "8px",
            transition: "color 0.3s ease"
          }}
          onMouseEnter={(e) => e.currentTarget.style.color = "#fff"}
          onMouseLeave={(e) => e.currentTarget.style.color = "#a0a0a0"}
          >
            🔔
          </button>
          <div style={{ position: "relative" }}>
            <button
              onClick={() => setShowProfileMenu(!showProfileMenu)}
              style={{
                background: "rgba(255, 255, 255, 0.05)",
                border: "1px solid rgba(255, 255, 255, 0.1)",
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                gap: "8px",
                fontSize: "14px",
                color: "#fff",
                fontWeight: "500",
                padding: "8px 16px",
                borderRadius: "8px",
                transition: "all 0.3s ease",
                letterSpacing: "-0.2px"
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.background = "rgba(255, 255, 255, 0.08)";
                e.currentTarget.style.borderColor = "rgba(255, 255, 255, 0.15)";
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = "rgba(255, 255, 255, 0.05)";
                e.currentTarget.style.borderColor = "rgba(255, 255, 255, 0.1)";
              }}
            >
              <span style={{ fontSize: "18px" }}>👤</span>
              My Profile
            </button>
            {showProfileMenu && (
              <div style={{
                position: "absolute",
                top: "calc(100% + 8px)",
                right: 0,
                background: "rgba(20, 20, 20, 0.98)",
                backdropFilter: "blur(20px)",
                border: "1px solid rgba(255, 255, 255, 0.1)",
                borderRadius: "12px",
                padding: "8px",
                boxShadow: "0 8px 32px rgba(0,0,0,0.4)",
                minWidth: "160px"
              }}>
                <button style={{
                  width: "100%",
                  padding: "10px 16px",
                  background: "none",
                  border: "none",
                  textAlign: "left",
                  cursor: "pointer",
                  fontSize: "14px",
                  color: "#fff",
                  borderRadius: "8px",
                  transition: "background 0.2s ease",
                  fontWeight: "500",
                  letterSpacing: "-0.2px"
                }}
                onMouseEnter={(e) => e.currentTarget.style.background = "rgba(255, 107, 53, 0.15)"}
                onMouseLeave={(e) => e.currentTarget.style.background = "none"}
                >
                  Logout
                </button>
              </div>
            )}
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <motion.div
        style={{
          display: "grid",
          gridTemplateColumns: "1.1fr 0.9fr",
          gap: "80px",
          maxWidth: "1440px",
          margin: "0 auto",
          padding: "100px 80px 120px",
          alignItems: "center",
        }}
        initial="hidden"
        animate="visible"
        variants={staggerContainer}
      >
        {/* Left Content */}
        <motion.div variants={fadeUp}>
          <div style={{
            display: "inline-block",
            padding: "6px 16px",
            background: "rgba(255, 107, 53, 0.1)",
            border: "1px solid rgba(255, 107, 53, 0.2)",
            borderRadius: "24px",
            marginBottom: "32px"
          }}>
            <span style={{
              fontSize: "12px",
              fontWeight: "600",
              color: "#ff6b35",
              letterSpacing: "0.5px",
              textTransform: "uppercase"
            }}>
              Professional Design Platform
            </span>
          </div>

          <h1
            style={{
              fontSize: "64px",
              fontWeight: "800",
              color: "#fff",
              marginBottom: "28px",
              lineHeight: "1.1",
              letterSpacing: "-2px",
            }}
          >
            AI-driven Interior
            <br />
            <span style={{
              background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              backgroundClip: "text"
            }}>
              Proposals in Minutes
            </span>
          </h1>

          <p
            style={{
              fontSize: "18px",
              color: "rgba(255, 255, 255, 0.7)",
              marginBottom: "48px",
              lineHeight: "1.8",
              letterSpacing: "-0.3px",
              fontWeight: "400"
            }}
          >
            ASSEMBLE은 사용자의 요청사항에 맞게
            <br />
            AI 기반 인테리어를 추천합니다
          </p>

          <div style={{ display: "flex", gap: "16px" }}>
            <motion.button
              style={{
                padding: "16px 40px",
                fontSize: "15px",
                fontWeight: "600",
                border: "none",
                borderRadius: "12px",
                background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
                color: "#fff",
                cursor: "pointer",
                transition: "all 0.3s ease",
                boxShadow: "0 8px 24px rgba(255, 107, 53, 0.35)",
                letterSpacing: "-0.2px"
              }}
              whileHover={{ 
                scale: 1.02,
                boxShadow: "0 12px 32px rgba(255, 107, 53, 0.45)"
              }}
              whileTap={{ scale: 0.98 }}
            >
              Get Started
            </motion.button>

            <motion.button
              style={{
                padding: "16px 40px",
                fontSize: "15px",
                fontWeight: "600",
                border: "1px solid rgba(255, 255, 255, 0.15)",
                borderRadius: "12px",
                background: "rgba(255, 255, 255, 0.05)",
                backdropFilter: "blur(10px)",
                color: "#fff",
                cursor: "pointer",
                transition: "all 0.3s ease",
                letterSpacing: "-0.2px"
              }}
              whileHover={{ 
                background: "rgba(255, 255, 255, 0.08)",
                borderColor: "rgba(255, 255, 255, 0.25)"
              }}
              whileTap={{ scale: 0.98 }}
            >
              Learn More
            </motion.button>
          </div>
        </motion.div>

        {/* Right Image */}
        <motion.div
          variants={fadeUp}
          style={{
            borderRadius: "20px",
            overflow: "hidden",
            boxShadow: "0 24px 80px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.08)",
            position: "relative"
          }}
        >
          <div style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "linear-gradient(135deg, rgba(255, 107, 53, 0.15) 0%, transparent 100%)",
            zIndex: 1
          }} />
          <img
            src="https://image.hanssem.com/hsimg/upload/homeIdea/2025/10/15/1760508599558_057278.jpg?w=1500"
            alt="Interior Design"
            style={{
              width: "100%",
              height: "560px",
              objectFit: "cover",
              display: "block",
            }}
          />
        </motion.div>
      </motion.div>

      {/* Features Section */}
      <motion.div
        style={{
          background: "linear-gradient(180deg, #0a0a0a 0%, #141414 100%)",
          padding: "120px 80px",
          borderTop: "1px solid rgba(255, 255, 255, 0.08)"
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true }}
        variants={staggerContainer}
      >
        <div style={{ maxWidth: "1440px", margin: "0 auto" }}>
          <motion.div variants={fadeUp} style={{ textAlign: "center", marginBottom: "80px" }}>
            <h2
              style={{
                fontSize: "42px",
                fontWeight: "700",
                color: "#fff",
                marginBottom: "16px",
                letterSpacing: "-1px"
              }}
            >
              디자이너를 위한 혁신적인 기능
            </h2>
            <p style={{
              fontSize: "16px",
              color: "rgba(255, 255, 255, 0.5)",
              letterSpacing: "-0.2px"
            }}>
              전문가를 위한 프로페셔널 인테리어 솔루션
            </p>
          </motion.div>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(4, 1fr)",
              gap: "24px",
            }}
          >
            {[
              {
                icon: <Lightbulb size={32} strokeWidth={1.5} />,
                title: "AI 자동 생성",
                description: "최첨단 AI 기술로 당신만의 맞춤형 인테리어를 즉시 생성합니다",
              },
              {
                icon: <Clock size={32} strokeWidth={1.5} />,
                title: "빠른 디자인",
                description: "몇 분 안에 다양한 스타일의 인테리어 시안을 확인하세요",
              },
              {
                icon: <Package size={32} strokeWidth={1.5} />,
                title: "무한한 아이디어",
                description: "다양한 컨셉과 스타일로 당신의 공간을 완벽하게 연출합니다",
              },
              {
                icon: <TrendingUp size={32} strokeWidth={1.5} />,
                title: "프로젝트 관리",
                description: "진행 중인 모든 프로젝트를 한눈에 관리하고 추적하세요",
              },
            ].map((feature, index) => (
              <motion.div
                key={index}
                style={{
                  background: "rgba(255, 255, 255, 0.03)",
                  backdropFilter: "blur(20px)",
                  padding: "40px 28px",
                  borderRadius: "16px",
                  border: "1px solid rgba(255, 255, 255, 0.08)",
                  cursor: "pointer",
                  transition: "all 0.4s cubic-bezier(0.22, 1, 0.36, 1)",
                  position: "relative",
                  overflow: "hidden"
                }}
                variants={fadeUp}
                whileHover={{
                  y: -8,
                  background: "rgba(255, 255, 255, 0.05)",
                  borderColor: "rgba(255, 107, 53, 0.3)",
                }}
                onMouseEnter={(e) => {
                  const overlay = e.currentTarget.querySelector('.feature-overlay');
                  if (overlay) overlay.style.opacity = '1';
                }}
                onMouseLeave={(e) => {
                  const overlay = e.currentTarget.querySelector('.feature-overlay');
                  if (overlay) overlay.style.opacity = '0';
                }}
              >
                <div 
                  className="feature-overlay"
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    background: "linear-gradient(135deg, rgba(255, 107, 53, 0.05) 0%, transparent 100%)",
                    opacity: 0,
                    transition: "opacity 0.4s ease",
                    pointerEvents: "none"
                  }}
                />
                
                <div
                  style={{
                    width: "64px",
                    height: "64px",
                    margin: "0 0 24px 0",
                    borderRadius: "12px",
                    background: "linear-gradient(135deg, rgba(255, 107, 53, 0.15) 0%, rgba(255, 77, 0, 0.15) 100%)",
                    border: "1px solid rgba(255, 107, 53, 0.2)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    color: "#ff6b35",
                  }}
                >
                  {feature.icon}
                </div>

                <h3
                  style={{
                    fontSize: "18px",
                    fontWeight: "600",
                    color: "#fff",
                    marginBottom: "12px",
                    letterSpacing: "-0.3px"
                  }}
                >
                  {feature.title}
                </h3>

                <p
                  style={{
                    fontSize: "14px",
                    color: "rgba(255, 255, 255, 0.6)",
                    lineHeight: "1.7",
                    margin: 0,
                    letterSpacing: "-0.2px"
                  }}
                >
                  {feature.description}
                </p>
              </motion.div>
            ))}
          </div>
        </div>
      </motion.div>

      {/* Stats Section */}
      <motion.div
        style={{
          padding: "100px 80px",
          maxWidth: "1440px",
          margin: "0 auto",
          background: "#0a0a0a"
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true }}
        variants={staggerContainer}
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gap: "60px",
            background: "rgba(255, 255, 255, 0.03)",
            backdropFilter: "blur(20px)",
            padding: "80px 60px",
            borderRadius: "20px",
            border: "1px solid rgba(255, 255, 255, 0.08)",
          }}
        >
          {[
            { value: "10,000+", label: "완성된 프로젝트" },
            { value: "5,000+", label: "만족한 사용자" },
            { value: "50+", label: "디자인 스타일" },
            { value: "99%", label: "고객 만족도" },
          ].map((stat, index) => (
            <motion.div
              key={index}
              style={{ textAlign: "center" }}
              variants={fadeUp}
            >
              <h2
                style={{
                  fontSize: "56px",
                  fontWeight: "800",
                  background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  backgroundClip: "text",
                  marginBottom: "12px",
                  letterSpacing: "-2px"
                }}
              >
                {stat.value}
              </h2>
              <p
                style={{
                  fontSize: "14px",
                  color: "rgba(255, 255, 255, 0.6)",
                  margin: 0,
                  fontWeight: "500",
                  letterSpacing: "-0.2px"
                }}
              >
                {stat.label}
              </p>
            </motion.div>
          ))}
        </div>
      </motion.div>
    </main>
  );
}

export default Hero;
